import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"蠱","description":"焦氏易林注 - 蠱","frontmatter":{"title":"蠱","description":"焦氏易林注 - 蠱"},"headers":[],"relativePath":"classics/jiaoyilin/018.md","filePath":"classics/jiaoyilin/018.md"}'),l={name:"classics/jiaoyilin/018.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蠱" tabindex="-1">蠱 <a class="header-anchor" href="#蠱" aria-label="Permalink to “蠱”">​</a></h1><h3 id="蠱-1" tabindex="-1">蠱 <a class="header-anchor" href="#蠱-1" aria-label="Permalink to “蠱”">​</a></h3><h3 id="蠱之乾" tabindex="-1">蠱之乾 <a class="header-anchor" href="#蠱之乾" aria-label="Permalink to “蠱之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>首澤與目，載受福慶。我有好爵，與汝相迎。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《蠱》象。艮為首、為目，震為福慶、為爵，三至上正反震故曰相迎。《易中孚九二》：&quot;我有好爵，與爾靡之&quot;。靡，共也。亦以二至五正反震故曰共。凡林詞用象，多本之《易》。○汝，從宋元本，汲古作喜。</p><h3 id="蠱之坤" tabindex="-1">蠱之坤 <a class="header-anchor" href="#蠱之坤" aria-label="Permalink to “蠱之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>，歲暮偏蔽。寵名捐棄，君衰在位。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用《蠱》象。震為輿、為聲，故曰，皆車聲也。坤為歲、為莫，艮為名，兌毀故曰捐棄。震為君。○，宋元本作轠，依汲古。偏，依宋元本，汲古作編。捐棄，汲古作棄損，非。棄蔽為韻。，音田。，音雷。哀，汲古作襄，依宋元本。</p><h3 id="蠱之屯" tabindex="-1">蠱之屯 <a class="header-anchor" href="#蠱之屯" aria-label="Permalink to “蠱之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>折若蔽日，屏遮王目。司馬無良，平子沒傷。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>《楚詞》：&quot;折若木以指日兮&quot;，註：若，木名。震為木，坎折坎蔽，離伏，故蔽日、故遮目。震為王、為馬，坤惡故無良。坎為平，震為子。《左傳》：&quot;魯伐季平子，平子登臺三請，弗許，叔孫氏之司馬鬷戾言於眾曰：無季氏是無叔孫氏也，遂救季氏&quot;，公徒敗事在昭二十五年。○若，依宋元本，汲古作箬，非。</p><h3 id="蠱之蒙" tabindex="-1">蠱之蒙 <a class="header-anchor" href="#蠱之蒙" aria-label="Permalink to “蠱之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>家在海隅，繞旋深流。王孫單行，無妄以趨。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮家坤海，坎水坤水，故曰深流。震為王，艮為孫，坤寡，故曰王孫單行。震為行，坎險故曰無妄。妄，西漢人多作望。○汲古下多&quot;固陰冱寒&quot;四句，與上義不屬，顯為別一林詞，故從宋元本。</p><h3 id="蠱之需" tabindex="-1">蠱之需 <a class="header-anchor" href="#蠱之需" aria-label="Permalink to “蠱之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>執義秉德，不危不殆。延頸盤桓，安其室垣。屯耗未得，終無大恤。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>伏《晉》。坤為義，乾為德，艮手為執、為秉，坎為危殆，艮為安，故不危殆。艮為頸，艮止故盤桓。艮為室垣、為安。○垣，從汲古，宋元本作檀，非。</p><h3 id="蠱之訟" tabindex="-1">蠱之訟 <a class="header-anchor" href="#蠱之訟" aria-label="Permalink to “蠱之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>長舌亂家，大斧破車。陰陽不得，姬薑衰憂。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。兌為舌，震形亦兌而長，故曰長舌。坤為亂，艮覆，故曰亂家。兌為斧，震形長，故曰大斧。坎破坤車。訟乾上升，水下降，故陰陽不相得。震姬巽薑，坎憂。姬薑婚媾，今陰陽既不相得，故姬薑衰憂也。○得，依宋元本，汲古作順。</p><h3 id="蠱之師" tabindex="-1">蠱之師 <a class="header-anchor" href="#蠱之師" aria-label="Permalink to “蠱之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>二人共路，東趨西步。千里之外，不相知處。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為人，坤數二故曰二人。震為路、為東、為趨步，坎為西，故東趨西步。坤為千里，坎為隱伏，故不相知處。○共，宋元本作異，依汲古。</p><h3 id="蠱之比" tabindex="-1">蠱之比 <a class="header-anchor" href="#蠱之比" aria-label="Permalink to “蠱之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>視暗不明，雲蔽日光。不見子都，鄭人心傷。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>離為視、為明、為日光，坎為雲、為隱伏，離伏故曰暗、曰蔽、曰不見。《詩鄭風》、《毛傳》&quot;子都，男子之美稱&quot;，蓋艮象也。坎為平、為鄭，《說文》：&quot;鄭，地町町然平也&quot;。坎為心、為憂傷。○不明，依汲古，與下光韻，宋元本作不見，非。</p><h3 id="蠱之小畜" tabindex="-1">蠱之小畜 <a class="header-anchor" href="#蠱之小畜" aria-label="Permalink to “蠱之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>初憂後喜，與福為市。八●列陳，飲御嘉友。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏《豫》。坎為憂，震為喜、為福，巽為市，坤卦數八，震為樂，故曰八●。八●，樂舞也。震為陳、為飲御，陰遇陽為朋友，謂《豫》四也。</p><h3 id="蠱之履" tabindex="-1">蠱之履 <a class="header-anchor" href="#蠱之履" aria-label="Permalink to “蠱之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>童妾獨宿，長女未室，利無所得。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>兌為妾、為少女，故曰童妾。巽為伏、為寡，故曰獨宿。巽為長女，艮為室，艮伏，故未室。巽為利，兌毀折，故無得。○童，依宋元本，汲古作僮，伏艮為僮僕，象亦得。</p><h3 id="蠱之泰" tabindex="-1">蠱之泰 <a class="header-anchor" href="#蠱之泰" aria-label="Permalink to “蠱之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>玄黃四塞，陰雌伏謀。呼我牆屋，為巫所識。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為玄黃，卦數四，坤閉，故曰四塞。坤為陰、為雌、為謀，伏巽為伏，故曰伏謀。震為呼，上坤為牆屋，兌為巫。</p><h3 id="蠱之否" tabindex="-1">蠱之否 <a class="header-anchor" href="#蠱之否" aria-label="Permalink to “蠱之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>中歲摧頹，常恐衰微。老復賴慶，五羖為相。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為歲，巽為隕落、為摧頹，坤為老、為衰微，乾為慶，在後，故老復有慶也。巽數五，伏兌為羊。《史記》：&quot;穆公以五羖羊皮贖百裡奚相秦&quot;。 ○頹，從宋元本，汲古作隤。</p><h3 id="蠱之同人" tabindex="-1">蠱之同人 <a class="header-anchor" href="#蠱之同人" aria-label="Permalink to “蠱之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>伯氏殺牛，行悖天時。亳社夷燒，朝歌邱墟。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>伏《師》。震為伯，坤為牛、為殺，故曰伯氏殺牛。震為行，坤為悖，乾為天，乾伏，故悖天時。震為子，商，子姓。亳社，朝歌，子姓之社稷都城也。離為火，坤為社、為墟，又震為旦、為歌，故曰朝歌。○殺牛，依汲古，宋元作羊。《既濟》雲&quot;東鄰殺牛，不如西鄰之禴祭，實受其福&quot;，漢儒皆謂東鄰指紂，林詞本此。</p><h3 id="蠱之大有" tabindex="-1">蠱之大有 <a class="header-anchor" href="#蠱之大有" aria-label="Permalink to “蠱之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>日短夜長，祿命不光。早離父母，免見憂傷。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>不光，宋元本作分張，依汲古。卦旁通《比》。比上坎，坎為冬、為夜，離不見，故日短夜長。乾為祿，坤黑故不光。大有、比、坎、離皆在外，乾坤在內，故曰早離父母。</p><h3 id="蠱之謙" tabindex="-1">蠱之謙 <a class="header-anchor" href="#蠱之謙" aria-label="Permalink to “蠱之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>採唐沬鄉，徼期桑中。失期不會，憂思忡忡。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《噬嗑》。 ○徼期、忡忡，依汲古，宋元本作期於、作約帶。失期，依宋元本，汲古作失心。</p><h3 id="蠱之豫" tabindex="-1">蠱之豫 <a class="header-anchor" href="#蠱之豫" aria-label="Permalink to “蠱之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>昧視無光，夜不見明。冥抵空床，季葉逃亡。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為視、為光，坎昧故無光，坎夜故不見明。坎為晦冥，艮為床，坤虛故曰空床。艮手為抵，艮為季，震為葉，坤為亡。</p><h3 id="蠱之隨" tabindex="-1">蠱之隨 <a class="header-anchor" href="#蠱之隨" aria-label="Permalink to “蠱之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>舉趾振翼，南至嘉國。見我伯姊，與惠相得。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為趾、為翼、為舉、為振、為南，艮為國，故南至嘉國。互巽為長女，故曰伯姊。兌為見也。</p><h3 id="蠱之蠱" tabindex="-1">蠱之蠱 <a class="header-anchor" href="#蠱之蠱" aria-label="Permalink to “蠱之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>魴生江淮，一轉為百。周流四海，無有難惡。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為魚、為魴，互大坎為江淮，數一，震為百，故曰一轉為百，言生殖速也。震為周，兌為海，震卦數四，故曰四海。○魴，汲古作紡，依宋元本。四海，宋元本作天下，汲古作四浸，依局本。</p><h3 id="蠱之臨" tabindex="-1">蠱之臨 <a class="header-anchor" href="#蠱之臨" aria-label="Permalink to “蠱之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>則天順時，周流其墟。與樂並居，無有咎憂。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為順，震為時，伏乾，故則天順時。震為周、為樂，坤水為流、為墟、為憂，震樂故無憂。○無有，宋本作無元，依元本、汲古。</p><h3 id="蠱之觀" tabindex="-1">蠱之觀 <a class="header-anchor" href="#蠱之觀" aria-label="Permalink to “蠱之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>蠆室蜂戶，螫我手足。不可進取，為吾害咎。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《泰》。《泰》通《否》。巽坤與觀同象。巽為蟲，故曰蠆蜂，艮室坤戶，艮為手，伏震為足，坤為毒，故螫我手足。</p><h3 id="蠱之噬嗑" tabindex="-1">蠱之噬嗑 <a class="header-anchor" href="#蠱之噬嗑" aria-label="Permalink to “蠱之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>公孫駕驪，載遊東齊。延陵悅產，遺季紵衣。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《益》。《益》震艮巽，《噬嗑》震艮伏巽，故語同。</p><h3 id="蠱之賁" tabindex="-1">蠱之賁 <a class="header-anchor" href="#蠱之賁" aria-label="Permalink to “蠱之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>轉作驪山，大失人心。劉季發怒，禽滅子嬰。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮山震馬，故曰驪山。震為人、為大，坎為心、為失，艮為季、為嬰，言秦役萬民築驪山，劉季因民怨而滅秦也。震為怒、為子，坎滅。○人心，汲古作元心，禽，汲古作命，均依宋元本。</p><h3 id="蠱之剝" tabindex="-1">蠱之剝 <a class="header-anchor" href="#蠱之剝" aria-label="Permalink to “蠱之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>羊腸九縈，相推稍前。止須王孫，乃能上天。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>伏兌為羊，坤為囊、為腸，伏乾，數九，故曰九縈。艮手為推、為前，艮為孫，乾為王，故曰王孫。艮為天，在上故曰上天。《史記佞幸傳》：&quot;鄧通南安人，孝文帝夢欲上天不能，有一黃頭郎從後推之上天，覺而求得鄧通&quot;。○能，汲古作得，從宋元本。羊腸阪在蒲阪九折，《史記》：&quot;魏伐趙，斷羊腸&quot;是也。</p><h3 id="蠱之復" tabindex="-1">蠱之復 <a class="header-anchor" href="#蠱之復" aria-label="Permalink to “蠱之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>螮蝀充側，佞人傾惑。女謁橫行，正道壅塞。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蟲，震玄黃，故曰螮蝀。螮蝀，虹也。震為人、為言，故曰佞人。坤為惑，伏巽為傾。震為謁、為行，坤陰故曰女謁。震為道，坤閉故壅塞。○螮，《毛詩》作蝃，謂刺淫，林謂刺佞，與毛異。</p><h3 id="蠱之無妄" tabindex="-1">蠱之無妄 <a class="header-anchor" href="#蠱之無妄" aria-label="Permalink to “蠱之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>福祿不遂，家多怪祟。麋鹿悲鳴，思其大雄。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為福祿，艮為家，震為麋鹿、為鳴，乾為大雄，伏坤為悲、為思。○鳴，宋元本作啼，從汲古。</p><h3 id="蠱之大畜" tabindex="-1">蠱之大畜 <a class="header-anchor" href="#蠱之大畜" aria-label="Permalink to “蠱之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>雲雷因積，大雨重迭。久不見日，使我心悒。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為雷，伏坤為雲，兌為雨，乾大故曰大雨，艮止故曰因積、曰重迭。又伏坤亦為水、為重也。○使我心悒，宋本作使心悒悒，依汲古。</p><h3 id="蠱之頤" tabindex="-1">蠱之頤 <a class="header-anchor" href="#蠱之頤" aria-label="Permalink to “蠱之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>三河俱合，水怒踴躍。壞我王屋，民困於食。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震數三，坤為水，重坤，故曰三河俱合。震為怒、為踴躍、為王，艮為屋，故曰王屋。坤為壞、為民，震口為食，坤虛，故無食。</p><h3 id="蠱之大過" tabindex="-1">蠱之大過 <a class="header-anchor" href="#蠱之大過" aria-label="Permalink to “蠱之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>冒雨夜行，早遍都城。更相覆傾，終無所成。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏震為行，艮為冒，兌為雨，坤為夜，故冒雨夜行。坤為都城，巽隕落故曰傾，正反巽故更相覆傾。艮為終、為成，坤亡故無成。全用伏象。○都，依汲古，宋元本作闢。汲古多&quot;三頭兩眼，不見其真&quot;二句，宋本無。</p><h3 id="蠱之坎" tabindex="-1">蠱之坎 <a class="header-anchor" href="#蠱之坎" aria-label="Permalink to “蠱之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>褒後生蛇，垂老皆微。倒跌衰耄，酉滅黃離。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>震為生，伏巽為蛇，艮為老耄，坎蹇，故倒跌。《說文》：&quot;酉，就也，老也&quot;。坎為滅。黃離，火也，離伏故曰滅。周以火德王，言褒姒滅周也。褒後生蛇者，言後生於龍漦也。餘似有故事，而註家皆不詳。○垂，依元本，汲古作經，皆依《大壯》之《大有》校，汲古作盲。倒，宋本、汲古作側，依元本。衰耄二字，亦依《大壯》之《大有》校，汲古作哀公，元本作衰公。酉，汲古作酒，依元本。滅，汲古作減，依宋本。</p><h3 id="蠱之離" tabindex="-1">蠱之離 <a class="header-anchor" href="#蠱之離" aria-label="Permalink to “蠱之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>鴻雁南飛，隨陽休息。轉逐天和，千里不衰。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏《坎》。互艮為鴻雁，震為南、為飛，離日為陽，艮為休息。震為轉逐，艮陽在上為天，坎為和，震為千，艮為裡。○陽，宋元本作時，依汲古。逐，汲古作送，依宋元本。裡，宋元本作歲，依汲古。衰，汲古作哀，依宋元本。</p><h3 id="蠱之鹹" tabindex="-1">蠱之鹹 <a class="header-anchor" href="#蠱之鹹" aria-label="Permalink to “蠱之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>後時失利，不得所欲。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為時，巽為利，兌折故失利，風散故不得所欲。○汲古祇上二句，宋元本多&quot;莫亨偕結，自逐自逐&quot;八字。</p><h3 id="蠱之恆" tabindex="-1">蠱之恆 <a class="header-anchor" href="#蠱之恆" aria-label="Permalink to “蠱之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>心多恨悔，出言為怪。梟鳴室北，聲醜可惡，請謁不得。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>伏坤為心、為恨悔，震為言、為鳴，伏艮為梟、為室，坤位北，故鳴室北。震為聲。《說苑》：&quot;齊景公築臺，臺成而不通，問之曰：有梟夜鳴，其聲可惡&quot;。 ○聲醜，元本作醜聲。○坤北證。</p><h3 id="蠱之遯" tabindex="-1">蠱之遯 <a class="header-anchor" href="#蠱之遯" aria-label="Permalink to “蠱之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>駟馬過隙，時難再得。尼父孔聖，繫而不食。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為馬，互巽數四，故曰駟馬。《史記留侯世家》：&quot;人生一世間，如白駒過隙&quot;。巽為隙，艮為時、為山，乾父故曰尼父。乾為聖，伏震為孔，巽繩為系，兌為食，兌覆故不食。《論語》：&quot;吾豈匏瓜也哉，焉能繫而不食&quot;。 ○駟馬，宋本、汲古作四，從元本。</p><h3 id="蠱之大壯" tabindex="-1">蠱之大壯 <a class="header-anchor" href="#蠱之大壯" aria-label="Permalink to “蠱之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>陰變為陽，女化為男。治道得通，君臣相承。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤伏乾出，巽伏震出，故曰陰變陽、女化男。震為道、為通，乾為君，伏艮為臣。</p><h3 id="蠱之晉" tabindex="-1">蠱之晉 <a class="header-anchor" href="#蠱之晉" aria-label="Permalink to “蠱之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>昆侖源口，流行不止。龍門砥柱，民不安處。母歸扶子，黃麑悅喜。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮山坎水，伏兌口，故曰昆侖源口。坤亦為水，與坎水合，故曰流行不止。艮為門，伏乾，故曰龍門。艮為石、為木，故曰砥柱。坤為民、為安處、為母，艮為少男，故曰扶子。艮為麑。坤為黃，伏兌為悅。○扶，依汲古，宋元本作孩子。</p><h3 id="蠱之明夷" tabindex="-1">蠱之明夷 <a class="header-anchor" href="#蠱之明夷" aria-label="Permalink to “蠱之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>葛藟蒙棘，華不得實。讒佞亂政，使恩壅塞。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《蒙》。蒙坎震，明夷亦坎震，象同。藟，汲古作累，依宋元本。</p><h3 id="蠱之家人" tabindex="-1">蠱之家人 <a class="header-anchor" href="#蠱之家人" aria-label="Permalink to “蠱之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>公無長驅，太王駿馬。非其所當，傷折為患。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為公、為長驅、為王、為馬，坎為患，坎蹇故傷折。○太，汲古作夭，依宋元本。所當、患，依汲古，宋元本作當所、作害。</p><h3 id="蠱之睽" tabindex="-1">蠱之睽 <a class="header-anchor" href="#蠱之睽" aria-label="Permalink to “蠱之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>大倉充盈，庶民蕃盛，年歲熟榮。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>伏艮故曰太倉。坎為眾，故曰充盈、曰庶民蕃盛。坎冬離夏，兌正秋，故曰年歲。離為火、為光明，故曰熟榮。○庶民蕃盛，依宋元本，汲古作萬物蕃成。</p><h3 id="蠱之蹇" tabindex="-1">蠱之蹇 <a class="header-anchor" href="#蠱之蹇" aria-label="Permalink to “蠱之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>執蕡照犧，為風所吹。火滅無光，不見玄黃。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《蠱》象。艮為執、為犧、為火、為照，巽為蕡。蕡，香草也。巽為風，兌為吹，艮為火、為光，坎黑巽伏，故火滅無光。震為玄黃，巽伏故不見。《周禮司煊》註：賁，燭，麻燭也，言執蕡火照牲，使熟而食也。○蕡，汲古作簧，依宋元本。</p><h3 id="蠱之解" tabindex="-1">蠱之解 <a class="header-anchor" href="#蠱之解" aria-label="Permalink to “蠱之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>鳥反故巢，歸其室家。心平意正，與叔相和。登高隕墜，失其寵貴。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為鳥、為反、為歸，坎為巢、為室、為心意、為平正、為和，震為登，伏巽為高、為隕墜，艮為貴，艮覆故失其寵貴。</p><h3 id="蠱之損" tabindex="-1">蠱之損 <a class="header-anchor" href="#蠱之損" aria-label="Permalink to “蠱之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>弩弛弓藏，良犬不行。內無怨女，征夫在堂。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>通《鹹》。互大坎為弩、為弓，艮止故曰弛。巽伏故曰藏。艮為犬，坎蹇故不行。以上皆用伏象。損內兌女，與上艮為夫婦，兌悅故不怨。互震在外故曰征夫。艮為堂也。</p><h3 id="蠱之益" tabindex="-1">蠱之益 <a class="header-anchor" href="#蠱之益" aria-label="Permalink to “蠱之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>特犧孔博，日新其德。文君燎獵，薑氏受福。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為牛，故曰特犧。震為孔，艮為日、為新，坤為文，震為君，故曰文君。艮為火，震為獵，故曰燎獵。巽為薑，震為福，言文王出獵遇薑尚，後受卦於齊也。○特，依宋元本。《書舜典》：&quot;格於藝祖，用特&quot;，註：特，一牛也。《禮郊特牲》註：用一牛故曰特牲。特犧，猶特牲也，汲古作牡，非。文君，從汲古，宋元本作文公，非。燎，從宋元本，汲古作出。</p><h3 id="蠱之夬" tabindex="-1">蠱之夬 <a class="header-anchor" href="#蠱之夬" aria-label="Permalink to “蠱之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>季秋孟冬，寒露霜降。大陰在庭，品物不生。雞犬夜鳴，家擾數驚。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，伏艮，故曰季秋。乾為冬，當亥，故曰孟冬。兌為露，伏坤為霜，故曰寒露霜降。伏坤為大陰、為品物，坤殺故不生。艮為庭、為犬，坤為夜，兌為雞、為鳴，乾為惕、為驚。艮為家。○季秋，汲古作秋季，依宋元本。品，依宋元本，汲古作庶。雞犬夜鳴，宋本、汲古作雞鳴犬吠，元本作雞矢，非。擾，依宋元本，汲古作憂，非。</p><h3 id="蠱之姤" tabindex="-1">蠱之姤 <a class="header-anchor" href="#蠱之姤" aria-label="Permalink to “蠱之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>心多恨悔，出門見怪。有蛇三足，醜聲可惡。嫫毋為媒，請求不得。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為心、為恨悔、為門戶，震為出，巽為蛇，震為足，數三，故曰有蛇三足。震為聲，坤為醜、為惡、為嫫毋，嫫毋，醜婦也。震為請，坤喪故不得。丁雲：任昉《述異記》：&quot;江中有獸名能，蛇精化也&quot;，《爾雅》三足能。○有，依宋元本，汲古作反。</p><h3 id="蠱之萃" tabindex="-1">蠱之萃 <a class="header-anchor" href="#蠱之萃" aria-label="Permalink to “蠱之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>虎豹爭強，道閉不通。小人歡訟，貪天之功。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為虎豹，坤為文，兌剛魯，三至上正反兌故曰爭強。艮為道，坤為閉，故不通。坤為小人，三至上正反皆兌口，故曰訟。《困》&quot;有言不信&quot;，即如是取象。○第四句依汲古，宋元本作&quot;貪夫受空&quot;。</p><h3 id="蠱之升" tabindex="-1">蠱之升 <a class="header-anchor" href="#蠱之升" aria-label="Permalink to “蠱之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>雞方啄粟，為狐所逐。走不得食，惶怖惕息。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>巽為雞、為粟，兌為啄，艮為狐，震為逐、為走，艮反向內，故曰為狐所逐。兌為食，坤閉故不得食。坤為憂，故惶怖惕息。○怖，宋本作懼，依汲古。</p><h3 id="蠱之困" tabindex="-1">蠱之困 <a class="header-anchor" href="#蠱之困" aria-label="Permalink to “蠱之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>陳媯敬仲，兆興齊薑。乃適營丘，八世大昌。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《噬嗑》。</p><h3 id="蠱之井" tabindex="-1">蠱之井 <a class="header-anchor" href="#蠱之井" aria-label="Permalink to “蠱之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>昊天白日，照臨我國。萬民康寧，鹹賴嘉福。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《晉》。</p><h3 id="蠱之革" tabindex="-1">蠱之革 <a class="header-anchor" href="#蠱之革" aria-label="Permalink to “蠱之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>雲夢大藪，索有所在。虞人共職，驪駒悅喜。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。坤為雲、為夢、為藪，《易》震索索，疏：心不安之貌。《釋文》懼也。坎坤皆為憂懼，故曰索。震為驩虞、為人、為驪駒、為悅喜。○索，依汲古，丁雲：即八索也，元本作嘉。又按：此二句似指漢高偽遊雲夢事，言其意別有所在，而不在獵也。</p><h3 id="蠱之鼎" tabindex="-1">蠱之鼎 <a class="header-anchor" href="#蠱之鼎" aria-label="Permalink to “蠱之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>獐鹿雉兔，群聚東國。盧黃白脊，俱往追逐。九齚十得，主君有喜。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《復》。《鼎》通《屯》，坤震象與復同。雉，宋本及汲古皆作雞，非，依元本。</p><h3 id="蠱之震" tabindex="-1">蠱之震 <a class="header-anchor" href="#蠱之震" aria-label="Permalink to “蠱之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>德惠孔明，主君復章，保其室堂。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為德、為孔，艮為明，震為主、為君，艮為章、為室堂。</p><h3 id="蠱之艮" tabindex="-1">蠱之艮 <a class="header-anchor" href="#蠱之艮" aria-label="Permalink to “蠱之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>天之所壞，不可強支。眾口嘈嘈，雖貴必危。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《夬》。艮為天，陽在上而窮，故壞，初至五正反兩震言相背，故曰嘈嘈。艮為貴，艮窮於上故雖貴必危也。</p><h3 id="蠱之漸" tabindex="-1">蠱之漸 <a class="header-anchor" href="#蠱之漸" aria-label="Permalink to “蠱之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>天之奧隅，堯舜所居。可以全身，保我邦家。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《觀》。艮為天，坎隱故曰奧。伏震為帝、為堯舜。</p><h3 id="蠱之歸妹" tabindex="-1">蠱之歸妹 <a class="header-anchor" href="#蠱之歸妹" aria-label="Permalink to “蠱之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>下泉苞稂，十年無王。荀伯遇時，憂念周京。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>坎為眾。稂，蕭蓍之屬。震為稂、為年、為王，兌數十，故曰十年，坎隱伏，故十年無王。震為伯、為時、為周，坎為憂念。下泉，《曹風》詩，《毛詩序》謂刺共公，劉毓崧雲何楷世本古義，據《易林》謂此詩為曹人美晉荀躒納敬王於成周而作，其說自昭二十二年王子朝作亂，至昭三十二年城成周為十年無王。《左傳》：&quot;天王使告於晉，曰：天降禍於周，俾我兄弟並有亂心，以為伯父憂，於今十年&quot;，正與《易林》合。荀，郇國後，稱荀伯，猶稱荀躒為知伯，荀字不誤也。○稂，元本訛恨，依宋本、汲古。無，依宋元本，汲古訛九。荀，元本作●，依宋本、汲古，是焦與《毛詩》異讀。</p><h3 id="蠱之豐" tabindex="-1">蠱之豐 <a class="header-anchor" href="#蠱之豐" aria-label="Permalink to “蠱之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>江淮海隅，眾利聚居。可以遨遊，卒歲無憂。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>互大坎故曰江淮海隅。巽為利，坎為聚，震為遨遊、為歲，震樂故無憂。</p><h3 id="蠱之旅" tabindex="-1">蠱之旅 <a class="header-anchor" href="#蠱之旅" aria-label="Permalink to “蠱之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>南山黃竹，三身六目。出入制命，東裡宣政。主尊君安，鄭國無患。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>丁雲：《穆天子傳》：&quot;天子命歌南山&quot;，又《詩》曰&quot;我徂黃竹&quot;，又曰予歸東土，和治諸夏。又曰吉日丁亥，天子入於南鄭&quot;，《易林》全用其意。離南艮山，伏震為竹、為黃，故曰南山黃竹。艮為身，納丙數三，離為目，納已數六，故曰三身六目。巽為命、為入，伏震為出、為東，艮為裡、為尊、為安，震為君主，伏坎為平、為鄭、為患。艮為國，兌悅故無患。○東裡，從元本，以下三句似指鄭子產事，而宋本、汲古皆作東皇，與《穆天子傳》&quot;予歸東土，和治諸夏&quot;語偶合，然下曰鄭國則皇似為訛字也，觀下《離》之《損》詞同，而黃竹作大木、三作丈是其證，丁詁未必然。</p><h3 id="蠱之巽" tabindex="-1">蠱之巽 <a class="header-anchor" href="#蠱之巽" aria-label="Permalink to “蠱之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>重譯貢芝，來除我憂。喜樂俱居，同其福休。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震故曰重譯。巽為香，故曰芝。坎為憂，坎伏，故憂除。兌為喜樂，伏震為福。○貢芝，依汲古，宋元本作置之，非。</p><h3 id="蠱之兌" tabindex="-1">蠱之兌 <a class="header-anchor" href="#蠱之兌" aria-label="Permalink to “蠱之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>南山高岡，麟鳳室堂。含和履中，國無災殃。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮為南山、為高岡，離為文、為麟鳳，艮為室堂，兌為和、為口、為含，伏震為履，伏坎為中，伏艮為國。</p><h3 id="蠱之渙" tabindex="-1">蠱之渙 <a class="header-anchor" href="#蠱之渙" aria-label="Permalink to “蠱之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>紫芝朱草，生長和氣。公屍侑食，福祿來下。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>巽為芝、為草，九宮之色，七赤九紫，震納庚，五行數九，故曰紫芝。坎赤故曰朱草。坎為和，震為生、為公、為屍。屍，主也，又為福祿。三四句，《鳧鷖》詩也。○生長和氣，依汲古，宋元作與仙為侶，《神農經》：&quot;山川雲雨五行四時、陰陽畫夜之精生五色神芝&quot;，皆為聖王休瑞。</p><h3 id="蠱之節" tabindex="-1">蠱之節 <a class="header-anchor" href="#蠱之節" aria-label="Permalink to “蠱之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>宮成室就，進樂相舞。英俊在堂，福祿光明。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為宮室，坎亦為室，艮為成，故曰宮成室就。震為樂舞、為英俊、為祿。艮為光明。</p><h3 id="蠱之中孚" tabindex="-1">蠱之中孚 <a class="header-anchor" href="#蠱之中孚" aria-label="Permalink to “蠱之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>商人子孫，資無所有。貪狼逐狐，留連都市。還轅內鄉，嘉喜何咎。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為商旅，震為人、為子，艮為孫，巽為利、為資，風散故無。艮為狼、為狐，《史記天官書》：&quot;狼變色多盜賊，下有四星曰弧，弧矢向狼多盜。&quot;然則狼弧二星皆主盜賊，貪狼逐狐者，言流為盜賊也。弧亦作狐。《秦本紀》據狼狐是其證。艮為流連、為都市，震為逐、為轅、為嘉喜。○人、有，依宋本，汲古作之、作食。貪狼，依宋元本，汲古作貪貝，誤。林意謂商人子孫流落都市為盜賊，若迴心向善則無咎也。</p><h3 id="蠱之小過" tabindex="-1">蠱之小過 <a class="header-anchor" href="#蠱之小過" aria-label="Permalink to “蠱之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>執贄入朝，獻其狐裘。元戎變安，沙漠以歡。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮手為執、為獻、為贄，巽入震朝，故曰執贄入朝。艮為狐，震為裘、為武人、為主，故曰元戌。艮為沙，震歡。</p><h3 id="蠱之既濟" tabindex="-1">蠱之既濟 <a class="header-anchor" href="#蠱之既濟" aria-label="Permalink to “蠱之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>湧泉汩汩，南流不絕。洿為淮海，敗壞邑里，家無所處。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>重坎故曰汩汩、曰不絕。離為南，故曰南流。重坎故曰淮海。坎折故敗壞。艮為邑里、為家。○汩汩，元本作滑滑，從宋本、汲古。元本無第三句，非。</p><h3 id="蠱之未濟" tabindex="-1">蠱之未濟 <a class="header-anchor" href="#蠱之未濟" aria-label="Permalink to “蠱之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>固陰冱寒，常冰不溫。凌人惰怠，大雹為災。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《噬嗑》。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
